import React from 'react';

interface ScoreBadgeProps {
  score: number;
  size?: 'sm' | 'md' | 'lg';
  showLabel?: boolean;
}

export const ScoreBadge: React.FC<ScoreBadgeProps> = ({ score, size = 'md', showLabel = false }) => {
  let colorClass = 'green';
  let label = 'Exceeding';

  if (score >= 90) {
    colorClass = 'green';
    label = 'Exceeding';
  } else if (score >= 80) {
    colorClass = 'blue';
    label = 'Strong';
  } else if (score >= 68) {
    colorClass = 'amber';
    label = 'Meeting';
  } else {
    colorClass = 'rose';
    label = 'Developing';
  }

  const sizeStyles = {
    sm: { padding: '2px 8px', fontSize: '0.75rem', fontWeight: 600 },
    md: { padding: '4px 12px', fontSize: '0.85rem', fontWeight: 700 },
    lg: { padding: '8px 18px', fontSize: '1.25rem', fontWeight: 800 }
  };

  return (
    <div style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}>
      <span className={`pill-badge ${colorClass}`} style={sizeStyles[size]}>
        {score}
        <span style={{ opacity: 0.7, fontSize: '0.7em', fontWeight: 500 }}>/100</span>
      </span>
      {showLabel && (
        <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
          {label}
        </span>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useApp } from '../../context/AppContext';
import { ManagerContextNote } from '../../types';
import { X, Calendar, FileText, Percent, UserCheck } from 'lucide-react';

interface ContextNoteModalProps {
  associateId: string;
  projectId: string;
  onClose: () => void;
}

export const ContextNoteModal: React.FC<ContextNoteModalProps> = ({ associateId, projectId, onClose }) => {
  const { addContextNote, associates, activeAssociate } = useApp();
  const targetAssociate = associates.find(a => a.id === associateId);

  const [category, setCategory] = useState<ManagerContextNote['category']>('Leave');
  const [impactDays, setImpactDays] = useState<number>(5);
  const [description, setDescription] = useState<string>('');
  const [adjustmentPercent, setAdjustmentPercent] = useState<number>(-15);

  const handleCategoryChange = (cat: ManagerContextNote['category']) => {
    setCategory(cat);
    if (cat === 'Leave') setAdjustmentPercent(-20);
    else if (cat === 'Onboarding') setAdjustmentPercent(-25);
    else if (cat === 'On-Call Firefighting') setAdjustmentPercent(-15);
    else if (cat === 'Special R&D Assignment') setAdjustmentPercent(0);
    else setAdjustmentPercent(-10);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!description.trim()) return;

    addContextNote({
      associateId,
      projectId,
      authorId: activeAssociate?.id || 'MGR-DEFAULT',
      authorName: activeAssociate ? `${activeAssociate.name} (${activeAssociate.title})` : 'Manager',
      periodLabel: 'Q1 2026',
      category,
      impactDays: Number(impactDays),
      description: description.trim(),
      baselineAdjustmentPercent: Number(adjustmentPercent)
    });

    onClose();
  };

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal-content" onClick={e => e.stopPropagation()}>
        <div className="modal-header">
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div className="stat-icon emerald" style={{ width: '38px', height: '38px' }}>
              <FileText size={18} />
            </div>
            <div>
              <h3 style={{ fontSize: '1.1rem' }}>Add Manager Context Note</h3>
              <p style={{ fontSize: '0.78rem', color: 'var(--text-muted)' }}>
                Apply fair baseline adjustments for {targetAssociate?.name}
              </p>
            </div>
          </div>
          <button className="btn btn-secondary btn-sm" onClick={onClose} style={{ padding: '6px' }}>
            <X size={18} />
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            <div className="form-group">
              <label className="form-label">Context Category</label>
              <select
                className="form-control"
                value={category}
                onChange={e => handleCategoryChange(e.target.value as any)}
              >
                <option value="Leave">Approved Leave (Parental, Medical, Annual)</option>
                <option value="On-Call Firefighting">24/7 Production On-Call & Firefighting</option>
                <option value="Onboarding">New Hire / Transfer Onboarding Ramp-up</option>
                <option value="Special R&D Assignment">Dedicated R&D Architecture Spike</option>
                <option value="Mentorship">Intensive Junior Engineer Mentorship</option>
              </select>
            </div>

            <div className="grid-2">
              <div className="form-group">
                <label className="form-label">Duration Impact (Working Days)</label>
                <input
                  type="number"
                  min="1"
                  max="60"
                  className="form-control"
                  value={impactDays}
                  onChange={e => setImpactDays(Number(e.target.value))}
                />
              </div>

              <div className="form-group">
                <label className="form-label">Baseline Target Scaling (% adjustment)</label>
                <input
                  type="number"
                  min="-80"
                  max="50"
                  className="form-control"
                  value={adjustmentPercent}
                  onChange={e => setAdjustmentPercent(Number(e.target.value))}
                />
                <span style={{ fontSize: '0.72rem', color: 'var(--text-dim)', marginTop: '2px' }}>
                  e.g., -20% lowers expected story point quota by 20%
                </span>
              </div>
            </div>

            <div className="form-group">
              <label className="form-label">Context Explanation & Justification</label>
              <textarea
                className="form-control"
                rows={3}
                placeholder="Explain the background reason (e.g. 2 weeks paternity leave approved by HR, or sole on-call responder during cloud gateway migration)..."
                value={description}
                onChange={e => setDescription(e.target.value)}
                required
              />
            </div>
          </div>

          <div className="modal-footer">
            <button type="button" className="btn btn-secondary" onClick={onClose}>
              Cancel
            </button>
            <button type="submit" className="btn btn-primary">
              Record Context Note
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useApp } from '../../context/AppContext';
import { ManualDataEntry } from '../../types';
import { X, PlusCircle, Edit3, ShieldAlert } from 'lucide-react';

interface ManualEntryModalProps {
  associateId: string;
  projectId: string;
  onClose: () => void;
}

export const ManualEntryModal: React.FC<ManualEntryModalProps> = ({ associateId, projectId, onClose }) => {
  const { addManualEntry, associates, projects, activeAssociate } = useApp();
  const targetAssociate = associates.find(a => a.id === associateId);
  const targetProject = projects.find(p => p.id === projectId);

  const [dimension, setDimension] = useState<ManualDataEntry['dimension']>('Delivery');
  const [metricName, setMetricName] = useState<string>('');
  const [value, setValue] = useState<number>(5);
  const [unit, setUnit] = useState<string>('Story Points');
  const [reason, setReason] = useState<string>('');

  const handleDimensionChange = (dim: ManualDataEntry['dimension']) => {
    setDimension(dim);
    if (dim === 'Delivery') setUnit('Story Points');
    else if (dim === 'Quality') setUnit('Test Cases / Defect Fixes');
    else if (dim === 'Review') setUnit('Substantive Reviews');
    else if (dim === 'Documentation') setUnit('Technical Specs / Whitepapers');
    else setUnit('Operational Incidents Resolved');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!metricName.trim() || !reason.trim()) return;

    addManualEntry({
      associateId,
      projectId,
      dimension,
      metricName: metricName.trim(),
      value: Number(value),
      unit,
      reason: reason.trim(),
      enteredBy: activeAssociate ? activeAssociate.name : 'Authorized Manager',
      isOverride: false
    });

    onClose();
  };

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal-content" onClick={e => e.stopPropagation()}>
        <div className="modal-header">
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div className="stat-icon indigo" style={{ width: '38px', height: '38px' }}>
              <Edit3 size={18} />
            </div>
            <div>
              <h3 style={{ fontSize: '1.1rem' }}>Add Manual Metric / Overlay</h3>
              <p style={{ fontSize: '0.78rem', color: 'var(--text-muted)' }}>
                Non-destructive data entry for {targetAssociate?.name} on {targetProject?.name}
              </p>
            </div>
          </div>
          <button className="btn btn-secondary btn-sm" onClick={onClose} style={{ padding: '6px' }}>
            <X size={18} />
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            <div style={{
              background: 'rgba(99, 102, 241, 0.08)',
              border: '1px solid rgba(99, 102, 241, 0.2)',
              borderRadius: 'var(--radius-sm)',
              padding: '10px 12px',
              fontSize: '0.78rem',
              color: 'var(--text-muted)',
              display: 'flex',
              alignItems: 'center',
              gap: '8px'
            }}>
              <ShieldAlert size={16} color="var(--accent-primary-light)" style={{ flexShrink: 0 }} />
              <span>
                <strong>Audit Compliance:</strong> Manual entries never overwrite raw source records. They are tagged as <code>[MANUAL OVERLAY]</code> with your signature and timestamp.
              </span>
            </div>

            <div className="grid-2">
              <div className="form-group">
                <label className="form-label">Dimension</label>
                <select
                  className="form-control"
                  value={dimension}
                  onChange={e => handleDimensionChange(e.target.value as any)}
                >
                  <option value="Delivery">Delivery & Throughput</option>
                  <option value="Quality">Code Quality & Testing</option>
                  <option value="Review">Code Review & Mentorship</option>
                  <option value="Documentation">Architecture & Documentation</option>
                  <option value="Reliability">Operational Reliability</option>
                </select>
              </div>

              <div className="form-group">
                <label className="form-label">Metric Value</label>
                <input
                  type="number"
                  step="any"
                  min="0"
                  className="form-control"
                  value={value}
                  onChange={e => setValue(Number(e.target.value))}
                  required
                />
              </div>
            </div>

            <div className="grid-2">
              <div className="form-group">
                <label className="form-label">Metric Name</label>
                <input
                  type="text"
                  className="form-control"
                  placeholder="e.g. Offline Architecture Spike, Security Audit"
                  value={metricName}
                  onChange={e => setMetricName(e.target.value)}
                  required
                />
              </div>

              <div className="form-group">
                <label className="form-label">Units / Label</label>
                <input
                  type="text"
                  className="form-control"
                  value={unit}
                  onChange={e => setUnit(e.target.value)}
                  required
                />
              </div>
            </div>

            <div className="form-group">
              <label className="form-label">Business Justification & Audit Reason</label>
              <textarea
                className="form-control"
                rows={3}
                placeholder="Explain why this data is being added manually (e.g. Work performed on client tool that lacks API integration, or offline design spikes)..."
                value={reason}
                onChange={e => setReason(e.target.value)}
                required
              />
            </div>
          </div>

          <div className="modal-footer">
            <button type="button" className="btn btn-secondary" onClick={onClose}>
              Cancel
            </button>
            <button type="submit" className="btn btn-primary">
              Record Manual Entry
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useApp, DatePeriod } from '../../context/AppContext';
import { UserRole } from '../../types';
import { Calendar, RefreshCw, Shield, User, Check, Sparkles } from 'lucide-react';

export const Header: React.FC = () => {
  const {
    userRole,
    setUserRole,
    currentUserId,
    setCurrentUserId,
    associates,
    activeAssociate,
    selectedPeriod,
    setSelectedPeriod,
    triggerSync
  } = useApp();

  const [isSyncing, setIsSyncing] = useState(false);
  const [syncFeedback, setSyncFeedback] = useState<string | null>(null);

  const periods: DatePeriod[] = [
    { start: '2026-01-01', end: '2026-03-31', label: 'Q1 2026 (Active Period)' },
    { start: '2025-10-01', end: '2025-12-31', label: 'Q4 2025 (Historical)' },
    { start: '2025-01-01', end: '2025-12-31', label: 'Full Year 2025' }
  ];

  const handleRoleChange = (role: UserRole) => {
    setUserRole(role);
    // Automatically switch active user to match the persona role for demo convenience
    if (role === 'Engineer') {
      setCurrentUserId('A004'); // Elena Rostova (Engineer)
    } else if (role === 'Lead') {
      setCurrentUserId('A003'); // Marcus Chen (Lead)
    } else if (role === 'Delivery Head') {
      setCurrentUserId('A006'); // Sarah Jenkins (VP Delivery)
    }
  };

  const handleSyncNow = () => {
    setIsSyncing(true);
    setTimeout(() => {
      const res = triggerSync();
      setIsSyncing(false);
      setSyncFeedback(`Delta sync complete: +${res.inserted} new events`);
      setTimeout(() => setSyncFeedback(null), 3500);
    }, 800);
  };

  return (
    <header className="top-header">
      <div className="header-left">
        {/* Period Selector (Criteria 7) */}
        <div className="period-selector">
          <Calendar size={15} color="var(--accent-primary-light)" />
          <select
            className="role-select"
            value={selectedPeriod.label}
            onChange={e => {
              const p = periods.find(item => item.label === e.target.value);
              if (p) setSelectedPeriod(p);
            }}
          >
            {periods.map(p => (
              <option key={p.label} value={p.label}>
                {p.label}
              </option>
            ))}
          </select>
        </div>

        {/* Delta Sync Button (Criteria 8) */}
        <button
          className="btn btn-secondary btn-sm"
          onClick={handleSyncNow}
          disabled={isSyncing}
          title="Incremental delta sync across JIRA, Azure DevOps, Git, TestRail, SharePoint"
        >
          <RefreshCw size={14} className={isSyncing ? 'spin-animation' : ''} />
          <span>{isSyncing ? 'Syncing...' : 'Incremental Sync'}</span>
        </button>

        {syncFeedback && (
          <span className="pill-badge green" style={{ animation: 'fadeIn 0.2s ease' }}>
            <Check size={12} /> {syncFeedback}
          </span>
        )}
      </div>

      <div className="header-right">
        {/* RBAC Role Switcher (Criteria 10) */}
        <div className="role-switcher-card">
