import React from 'react';

interface RadarChartProps {
  dimensions: {
    delivery: number;
    quality: number;
    review: number;
    documentation: number;
    reliability: number;
  };
  benchmarkTargets?: {
    delivery: number;
    quality: number;
    review: number;
    documentation: number;
    reliability: number;
  };
  size?: number;
}

export const RadarChart: React.FC<RadarChartProps> = ({
  dimensions,
  benchmarkTargets = { delivery: 80, quality: 80, review: 75, documentation: 70, reliability: 80 },
  size = 320
}) => {
  const center = size / 2;
  const radius = (size / 2) - 45;

  const axes = [
    { key: 'delivery', label: 'Delivery', angle: -Math.PI / 2 },
    { key: 'quality', label: 'Quality', angle: -Math.PI / 2 + (2 * Math.PI / 5) },
    { key: 'review', label: 'Review Rigor', angle: -Math.PI / 2 + (4 * Math.PI / 5) },
    { key: 'documentation', label: 'Architecture', angle: -Math.PI / 2 + (6 * Math.PI / 5) },
    { key: 'reliability', label: 'Reliability', angle: -Math.PI / 2 + (8 * Math.PI / 5) }
  ];

  // Concentric polygon grid levels: 25%, 50%, 75%, 100%
  const levels = [0.25, 0.5, 0.75, 1.0];

  const getCoordinates = (value: number, angle: number) => {
    const normalized = Math.min(100, Math.max(0, value)) / 100;
    const r = normalized * radius;
    return {
      x: center + r * Math.cos(angle),
      y: center + r * Math.sin(angle)
    };
  };

  // Associate polygon points
  const points = axes.map(axis => {
    const val = (dimensions as any)[axis.key] || 0;
    const { x, y } = getCoordinates(val, axis.angle);
    return `${x},${y}`;
  }).join(' ');

  // Benchmark polygon points
  const benchPoints = axes.map(axis => {
    const val = (benchmarkTargets as any)[axis.key] || 75;
    const { x, y } = getCoordinates(val, axis.angle);
    return `${x},${y}`;
  }).join(' ');

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
      <svg width={size} height={size} style={{ overflow: 'visible' }}>
        <defs>
          <radialGradient id="radarFillGrad" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#6366f1" stopOpacity="0.5" />
            <stop offset="100%" stopColor="#8b5cf6" stopOpacity="0.15" />
          </radialGradient>
        </defs>

        {/* Concentric Grid Polygons */}
        {levels.map((lvl, idx) => {
          const polyPoints = axes.map(axis => {
            const r = lvl * radius;
            return `${center + r * Math.cos(axis.angle)},${center + r * Math.sin(axis.angle)}`;
          }).join(' ');

          return (
            <polygon
              key={idx}
              points={polyPoints}
              fill="transparent"
              stroke="rgba(255, 255, 255, 0.08)"
              strokeWidth="1"
            />
          );
        })}

        {/* Axis Spokes */}
        {axes.map((axis, idx) => {
          const endX = center + radius * Math.cos(axis.angle);
          const endY = center + radius * Math.sin(axis.angle);

          // Label placement offset
          const labelDist = radius + 24;
          const labelX = center + labelDist * Math.cos(axis.angle);
          const labelY = center + labelDist * Math.sin(axis.angle);

          return (
            <g key={idx}>
              <line
                x1={center}
                y1={center}
                x2={endX}
                y2={endY}
                stroke="rgba(255, 255, 255, 0.12)"
                strokeDasharray="2,2"
              />
              <text
                x={labelX}
                y={labelY}
                textAnchor="middle"
                dominantBaseline="central"
                fill="var(--text-muted)"
                fontSize="11"
                fontWeight="600"
                fontFamily="Inter, sans-serif"
              >
                {axis.label}
              </text>
            </g>
          );
        })}

        {/* Benchmark Silhouette Polygon */}
        <polygon
          points={benchPoints}
          fill="transparent"
          stroke="rgba(6, 182, 212, 0.6)"
          strokeWidth="1.5"
          strokeDasharray="4,3"
        />

        {/* Actual Associate Score Polygon */}
        <polygon
          points={points}
          fill="url(#radarFillGrad)"
          stroke="#818cf8"
          strokeWidth="2.5"
        />

        {/* Score Data Dots */}
        {axes.map((axis, idx) => {
          const val = (dimensions as any)[axis.key] || 0;
          const { x, y } = getCoordinates(val, axis.angle);
          return (
            <g key={idx}>
              <circle
                cx={x}
                cy={y}
                r="4.5"
                fill="#fff"
                stroke="#6366f1"
                strokeWidth="2"
              />
              <text
                x={x}
                y={y - 10}
                textAnchor="middle"
                fill="#fff"
                fontSize="10"
                fontWeight="700"
                fontFamily="Outfit, sans-serif"
              >
                {val}
              </text>
            </g>
          );
        })}
      </svg>

      {/* Legend */}
      <div style={{ display: 'flex', gap: '18px', marginTop: '8px', fontSize: '0.76rem', color: 'var(--text-muted)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
          <span style={{ width: '12px', height: '12px', borderRadius: '3px', background: 'rgba(99, 102, 241, 0.5)', border: '1px solid #818cf8' }} />
          <span>Actual Score</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
          <span style={{ width: '12px', height: '2px', background: 'var(--accent-cyan)', borderTop: '1px dashed var(--accent-cyan)' }} />
          <span>Calibrated Target</span>
        </div>
      </div>
    </div>
  );
};

import React from 'react';

interface SprintTrendPoint {
  sprint: string;
  storyPoints: number;
  prsMerged: number;
  reworkBounces: number;
}

interface SprintTrendChartProps {
  data?: SprintTrendPoint[];
  height?: number;
}

export const SprintTrendChart: React.FC<SprintTrendChartProps> = ({
  data = [
    { sprint: 'Sprint 21 (Jan 1-14)', storyPoints: 34, prsMerged: 12, reworkBounces: 2 },
    { sprint: 'Sprint 22 (Jan 15-28)', storyPoints: 42, prsMerged: 15, reworkBounces: 1 },
    { sprint: 'Sprint 23 (Jan 29-Feb 11)', storyPoints: 38, prsMerged: 14, reworkBounces: 3 },
    { sprint: 'Sprint 24 (Feb 12-25)', storyPoints: 48, prsMerged: 18, reworkBounces: 0 },
    { sprint: 'Sprint 25 (Feb 26-Mar 11)', storyPoints: 52, prsMerged: 19, reworkBounces: 2 },
    { sprint: 'Sprint 26 (Mar 12-25)', storyPoints: 46, prsMerged: 16, reworkBounces: 1 }
  ],
  height = 200
}) => {
  const maxPoints = Math.max(...data.map(d => d.storyPoints), 60);
  const width = 600;
  const paddingLeft = 40;
  const paddingRight = 20;
  const paddingTop = 20;
  const paddingBottom = 30;

  const chartWidth = width - paddingLeft - paddingRight;
  const chartHeight = height - paddingTop - paddingBottom;

  const getX = (index: number) => paddingLeft + (index / (data.length - 1)) * chartWidth;
  const getY = (val: number) => paddingTop + chartHeight - (val / maxPoints) * chartHeight;

  // Velocity points path
  const pointsPath = data.map((d, i) => `${i === 0 ? 'M' : 'L'} ${getX(i)} ${getY(d.storyPoints)}`).join(' ');
  const areaPath = `${pointsPath} L ${getX(data.length - 1)} ${paddingTop + chartHeight} L ${getX(0)} ${paddingTop + chartHeight} Z`;

  return (
    <div style={{ width: '100%', overflowX: 'auto' }}>
      <svg viewBox={`0 0 ${width} ${height}`} style={{ width: '100%', height: 'auto', minWidth: '480px' }}>
        <defs>
          <linearGradient id="velocityAreaGrad" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="#6366f1" stopOpacity="0.35" />
            <stop offset="100%" stopColor="#6366f1" stopOpacity="0.0" />
          </linearGradient>
        </defs>

        {/* Horizontal Grid lines */}
        {[0, 20, 40, 60].map(val => {
          const y = getY(val);
          return (
            <g key={val}>
              <line
                x1={paddingLeft}
                y1={y}
                x2={width - paddingRight}
                y2={y}
                stroke="rgba(255, 255, 255, 0.06)"
                strokeDasharray="3,3"
              />
              <text
                x={paddingLeft - 8}
                y={y}
                textAnchor="end"
                dominantBaseline="central"
                fill="var(--text-dim)"
                fontSize="10"
                fontFamily="JetBrains Mono"
              >
                {val}
              </text>
            </g>
          );
        })}

        {/* Area fill */}
        <path d={areaPath} fill="url(#velocityAreaGrad)" />

        {/* Line */}
        <path d={pointsPath} fill="none" stroke="#6366f1" strokeWidth="2.5" />

        {/* Points & Labels */}
        {data.map((d, i) => {
          const x = getX(i);
          const y = getY(d.storyPoints);
          return (
            <g key={i}>
              <circle cx={x} cy={y} r="4" fill="#fff" stroke="#6366f1" strokeWidth="2" />
              <text
                x={x}
                y={y - 10}
                textAnchor="middle"
                fill="#fff"
                fontSize="10"
                fontWeight="700"
                fontFamily="Outfit"
              >
                {d.storyPoints} pts
              </text>
              <text
                x={x}
                y={height - 10}
                textAnchor="middle"
                fill="var(--text-dim)"
                fontSize="9"
                fontFamily="Inter"
              >
                {d.sprint.split(' ')[0]} {d.sprint.split(' ')[1]}
              </text>
            </g>
          );
        })}
      </svg>

      <div style={{ display: 'flex', justifyContent: 'center', gap: '20px', marginTop: '6px', fontSize: '0.74rem', color: 'var(--text-muted)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
          <span style={{ width: '10px', height: '10px', borderRadius: '50%', background: '#6366f1' }} />
          <span>Sprint Story Points Delivered</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
          <span style={{ color: 'var(--accent-emerald)', fontWeight: 600 }}>Zero critical regression drops</span>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { CalculatedPerformanceReport, Associate } from '../../types';
import { X, Copy, Check, Download, Printer, FileText } from 'lucide-react';

interface ExportReportModalProps {
  report: CalculatedPerformanceReport;
  associate: Associate;
  onClose: () => void;
}

export const ExportReportModal: React.FC<ExportReportModalProps> = ({ report, associate, onClose }) => {
  const [copied, setCopied] = useState(false);

  const reportText = `================================================================================
PSIOG ENGINEERING PERFORMANCE REVIEW DOSSIER
Evaluation Period: ${report.periodLabel} (${report.periodStart} to ${report.periodEnd})
Generated by: Psiog Pulse Intelligent Engineering Engine
================================================================================

1. ASSOCIATE PROFILE
--------------------------------------------------------------------------------
Name:             ${associate.name}
Role / Title:     ${associate.title}
Primary Offering: ${associate.primaryOffering}
Corporate Email:  ${associate.email}
Overall Score:    ${report.overallScore} / 100
Rating Band:      ${report.ratingBand}

2. TIME-BOUND TENURE & ATTRIBUTION BREAKDOWN
--------------------------------------------------------------------------------
${report.tenureSegments.map(s => `• ${s.projectName} [${s.offering}]
  Tenure: ${s.startDate} to ${s.endDate} (${s.activeCalendarDays} calendar days, ${s.effectiveWorkingDays} effective days)
  Assigned Role: ${s.role} (Allocation: ${s.allocationPercentage}%)
  Output: ${s.activitiesCount.tickets} tickets, ${s.activitiesCount.prs} PRs, ${s.activitiesCount.reviews} reviews, ${s.activitiesCount.docs} SharePoint docs`).join('\n\n')}

3. MULTI-DIMENSIONAL SCORECARD
--------------------------------------------------------------------------------
• Velocity & Delivery:         ${report.dimensions.delivery.score}/100 (Weight: ${Math.round(report.dimensions.delivery.weight * 100)}%)
  Target: ${report.dimensions.delivery.benchmarkTarget}
  Metrics: ${JSON.stringify(report.dimensions.delivery.rawMetrics)}

• Code Quality & Stability:    ${report.dimensions.quality.score}/100 (Weight: ${Math.round(report.dimensions.quality.weight * 100)}%)
  Target: ${report.dimensions.quality.benchmarkTarget}
  Metrics: ${JSON.stringify(report.dimensions.quality.rawMetrics)}

• Peer Code Review Rigor:      ${report.dimensions.review.score}/100 (Weight: ${Math.round(report.dimensions.review.weight * 100)}%)
  Target: ${report.dimensions.review.benchmarkTarget}
  Metrics: ${JSON.stringify(report.dimensions.review.rawMetrics)}

• Architecture & Docs:         ${report.dimensions.documentation.score}/100 (Weight: ${Math.round(report.dimensions.documentation.weight * 100)}%)
  Target: ${report.dimensions.documentation.benchmarkTarget}
  Metrics: ${JSON.stringify(report.dimensions.documentation.rawMetrics)}

• Operational Reliability:     ${report.dimensions.reliability.score}/100 (Weight: ${Math.round(report.dimensions.reliability.weight * 100)}%)
  Target: ${report.dimensions.reliability.benchmarkTarget}
  Metrics: ${JSON.stringify(report.dimensions.reliability.rawMetrics)}

4. FAIRNESS & CONTEXT ADJUSTMENTS
--------------------------------------------------------------------------------
${report.contextAdjustments.notesApplied.length > 0 
  ? report.contextAdjustments.notesApplied.map(n => `- [${n.category}] ${n.description} (Adjustment: ${n.baselineAdjustmentPercent}%, recorded by ${n.authorName})`).join('\n')
  : 'None recorded for this period.'}

5. AI NARRATIVE & EXECUTIVE SUMMARY
--------------------------------------------------------------------------------
${report.aiInsights.executiveSummary}

Key Strengths:
${report.aiInsights.keyStrengths.map(s => `+ ${s}`).join('\n')}

Growth & Coaching Areas:
${report.aiInsights.growthAreas.map(g => `- ${g}`).join('\n')}

Anti-Gaming Status: ${report.antiGamingFlags.length === 0 ? 'Clean (0 flags)' : `${report.antiGamingFlags.length} flagged patterns requiring Lead review`}
================================================================================`;

  const handleCopy = () => {
    navigator.clipboard.writeText(reportText);
    setCopied(true);
    setTimeout(() => setCopied(false), 3000);
