              height: '360px',
              fontFamily: 'JetBrains Mono',
              fontSize: '0.78rem',
              background: '#0d1321',
              color: '#c7d2fe',
              border: '1px solid var(--border-color)',
              borderRadius: 'var(--radius-md)',
              padding: '16px',
              outline: 'none',
              resize: 'none',
              lineHeight: 1.45
            }}
          />
